     1	//! Borrowed accessor structs for reading boxed term layouts.
     2	
     3	use crate::atom::Atom;
     4	use crate::term::{Term, binary::Binary, shared_binary::SharedBinary};
     5	
     6	use super::{BoxedHeader, BoxedTag};
     7	
     8	/// Borrowed accessor for a tuple boxed term.
     9	#[derive(Copy, Clone, Debug)]
    10	pub struct Tuple {
    11	    ptr: *const u64,
    12	}
    13	
    14	impl Tuple {
    15	    pub fn new(term: Term) -> Option<Self> {
    16	        let ptr = header_ptr(term, BoxedTag::Tuple)?;
    17	        Some(Self { ptr })
    18	    }
    19	
    20	    pub fn arity(self) -> usize {
    21	        BoxedHeader::size(self.header())
    22	    }
    23	
    24	    pub fn get(self, index: usize) -> Option<Term> {
    25	        if index < self.arity() {
    26	            Some(Term::from_raw(self.word(1 + index)))
    27	        } else {
    28	            None
    29	        }
    30	    }
    31	
    32	    fn header(self) -> u64 {
    33	        self.word(0)
    34	    }
    35	
    36	    fn word(self, offset: usize) -> u64 {
    37	        // SAFETY: instances are only built from term pointers to stack/heap word
    38	        // arrays created by this module; callers must keep the backing storage
    39	        // alive while using the borrowed accessor.
    40	        unsafe { *self.ptr.add(offset) }
    41	    }
    42	}
    43	
    44	/// Borrowed accessor for a list cons cell.
    45	#[derive(Copy, Clone, Debug)]
    46	pub struct Cons {
    47	    ptr: *const u64,
    48	}
    49	
    50	impl Cons {
    51	    pub fn new(term: Term) -> Option<Self> {
    52	        if !term.is_list() {
    53	            return None;
    54	        }
    55	
    56	        Some(Self {
    57	            ptr: term.heap_ptr()?,
    58	        })
    59	    }
    60	
    61	    pub fn head(self) -> Term {
    62	        Term::from_raw(self.word(0))
    63	    }
    64	
    65	    pub fn tail(self) -> Term {
    66	        Term::from_raw(self.word(1))
    67	    }
    68	
    69	    fn word(self, offset: usize) -> u64 {
    70	        // SAFETY: see Tuple::word; cons accessors read the fixed two-word cell.
    71	        unsafe { *self.ptr.add(offset) }
    72	    }
    73	}
    74	
    75	/// Borrowed accessor for a boxed float.
    76	#[derive(Copy, Clone, Debug)]
    77	pub struct Float {
    78	    ptr: *const u64,
    79	}
    80	
    81	impl Float {
    82	    pub fn new(term: Term) -> Option<Self> {
    83	        let ptr = header_ptr(term, BoxedTag::Float)?;
    84	        Some(Self { ptr })
    85	    }
    86	
    87	    pub fn value(self) -> f64 {
    88	        // SAFETY: float payload is one u64 word immediately after the header.
    89	        f64::from_bits(unsafe { *self.ptr.add(1) })
    90	    }
    91	}
    92	
    93	/// Borrowed accessor for a boxed big integer storage layout.
    94	#[derive(Copy, Clone, Debug)]
    95	pub struct BigInt {
    96	    ptr: *const u64,
    97	}
    98	
    99	impl BigInt {
   100	    pub fn new(term: Term) -> Option<Self> {
   101	        let ptr = header_ptr(term, BoxedTag::BigInt)?;
   102	        Some(Self { ptr })
   103	    }
   104	
   105	    pub fn is_negative(self) -> bool {
   106	        self.word(1) == super::BIGINT_NEGATIVE_SIGN
   107	    }
   108	
   109	    pub fn limb_count(self) -> usize {
   110	        self.word(2) as usize
   111	    }
   112	
   113	    pub fn limbs(self) -> &'static [u64] {
   114	        let count = self.limb_count();
   115	        // SAFETY: the limb count is written by write_bigint, and the returned
   116	        // borrow points into caller-owned heap storage that must outlive use.
   117	        unsafe { std::slice::from_raw_parts(self.ptr.add(3), count) }
   118	    }
   119	
   120	    fn word(self, offset: usize) -> u64 {
   121	        // SAFETY: see Tuple::word.
   122	        unsafe { *self.ptr.add(offset) }
   123	    }
   124	}
   125	
   126	/// Borrowed accessor for a boxed closure.
   127	#[derive(Copy, Clone, Debug)]
   128	pub struct Closure {
   129	    ptr: *const u64,
   130	}
   131	
   132	impl Closure {
   133	    pub fn new(term: Term) -> Option<Self> {
   134	        let ptr = header_ptr(term, BoxedTag::Closure)?;
   135	        // SAFETY: `header_ptr` returned a boxed closure header pointer.
   136	        let header = unsafe { *ptr };
   137	        let size = BoxedHeader::size(header);
   138	        if size < 6 {
   139	            return None;
   140	        }
   141	
   142	        // SAFETY: closure payloads of size at least six contain the num_free
   143	        // word at offset four. Reject inconsistent sizes before exposing the
   144	        // accessor so metadata/free-var reads stay within the boxed object.
   145	        let num_free = unsafe { *ptr.add(4) } as usize;
   146	        if size != 6 + num_free {
   147	            return None;
   148	        }
   149	
   150	        Some(Self { ptr })
   151	    }
   152	
   153	    pub fn module(self) -> Option<Atom> {
   154	        Term::from_raw(self.word(1)).as_atom()
   155	    }
   156	
   157	    pub fn function_index(self) -> u64 {
   158	        self.word(2)
   159	    }
   160	
   161	    pub fn arity(self) -> u8 {
   162	        self.word(3) as u8
   163	    }
   164	
   165	    pub fn num_free(self) -> usize {
   166	        self.word(4) as usize
   167	    }
   168	
   169	    pub fn generation(self) -> u64 {
   170	        self.word(5)
   171	    }
   172	
   173	    pub fn unique_id(self) -> u64 {
   174	        self.word(6)
   175	    }
   176	
   177	    pub fn free_var(self, index: usize) -> Option<Term> {
   178	        if index < self.num_free() {
   179	            Some(Term::from_raw(self.word(7 + index)))
   180	        } else {
   181	            None
   182	        }
   183	    }
   184	
   185	    /// True when this closure is an export fun (`fun M:F/A`) written by
   186	    /// `write_export_fun`, marked by the sentinel generation.
   187	    pub fn is_export(self) -> bool {
   188	        self.generation() == super::EXPORT_FUN_GENERATION
   189	    }
   190	
   191	    /// Function atom of an export fun; `None` for ordinary closures.
   192	    pub fn export_function(self) -> Option<Atom> {
   193	        if self.is_export() {
   194	            Term::from_raw(self.word(2)).as_atom()
   195	        } else {
   196	            None
   197	        }
   198	    }
   199	
   200	    fn word(self, offset: usize) -> u64 {
   201	        // SAFETY: see Tuple::word.
   202	        unsafe { *self.ptr.add(offset) }
   203	    }
   204	}
