   206	/// Borrowed accessor for a flatmap boxed term.
   207	#[derive(Copy, Clone, Debug)]
   208	pub struct Map {
   209	    ptr: *const u64,
   210	}
   211	
   212	impl Map {
   213	    pub fn new(term: Term) -> Option<Self> {
   214	        let ptr = header_ptr(term, BoxedTag::Map)?;
   215	        Some(Self { ptr })
   216	    }
   217	
   218	    pub fn len(self) -> usize {
   219	        self.word(1) as usize
   220	    }
   221	
   222	    pub fn is_empty(self) -> bool {
   223	        self.len() == 0
   224	    }
   225	
   226	    pub fn key(self, index: usize) -> Option<Term> {
   227	        if index < self.len() {
   228	            Some(Term::from_raw(self.word(2 + index)))
   229	        } else {
   230	            None
   231	        }
   232	    }
   233	
   234	    pub fn value(self, index: usize) -> Option<Term> {
   235	        if index < self.len() {
   236	            Some(Term::from_raw(self.word(2 + self.len() + index)))
   237	        } else {
   238	            None
   239	        }
   240	    }
   241	
   242	    pub fn get(self, key: Term) -> Option<Term> {
   243	        (0..self.len()).find_map(|index| {
   244	            if self.key(index) == Some(key) {
   245	                self.value(index)
   246	            } else {
   247	                None
   248	            }
   249	        })
   250	    }
   251	
   252	    fn word(self, offset: usize) -> u64 {
   253	        // SAFETY: see Tuple::word.
   254	        unsafe { *self.ptr.add(offset) }
   255	    }
   256	}
