   258	/// Borrowed accessor for an off-heap reference-counted binary.
   259	#[derive(Copy, Clone, Debug)]
   260	pub struct ProcBin {
   261	    ptr: *const u64,
   262	}
   263	
   264	impl ProcBin {
   265	    pub fn new(term: Term) -> Option<Self> {
   266	        let ptr = header_ptr(term, BoxedTag::ProcBin)?;
   267	        // SAFETY: `header_ptr` returned a boxed ProcBin header pointer.
   268	        let header = unsafe { *ptr };
   269	        if BoxedHeader::size(header) != 2 {
   270	            return None;
   271	        }
   272	        // SAFETY: validated ProcBin layout has two payload words; word two is
   273	        // the raw Arc pointer and must be present/non-null before access.
   274	        if unsafe { *ptr.add(2) } == 0 {
   275	            return None;
   276	        }
   277	
   278	        Some(Self { ptr })
   279	    }
   280	
   281	    pub fn as_bytes(self) -> &'static [u8] {
   282	        SharedBinary::bytes_from_raw_word(self.arc_ptr_word())
   283	    }
   284	
   285	    pub fn len(self) -> usize {
   286	        self.as_bytes().len()
   287	    }
   288	
   289	    pub fn is_empty(self) -> bool {
   290	        self.len() == 0
   291	    }
   292	
   293	    pub fn shared_binary(self) -> SharedBinary {
   294	        SharedBinary::clone_from_raw_word(self.arc_ptr_word())
   295	    }
   296	
   297	    fn arc_ptr_word(self) -> u64 {
   298	        // SAFETY: ProcBin payload word two stores the raw `Arc<Vec<u8>>` pointer.
   299	        unsafe { *self.ptr.add(2) }
   300	    }
   301	}
   302	
   303	/// Borrowed accessor for a sub-binary view into an inline Binary or ProcBin.
   304	#[derive(Copy, Clone, Debug)]
   305	pub struct SubBinary {
   306	    ptr: *const u64,
   307	}
   308	
   309	impl SubBinary {
   310	    pub fn new(term: Term) -> Option<Self> {
   311	        let ptr = header_ptr(term, BoxedTag::SubBinary)?;
   312	        // SAFETY: `header_ptr` returned a boxed SubBinary header pointer.
   313	        let header = unsafe { *ptr };
   314	        if BoxedHeader::size(header) != 4 {
   315	            return None;
   316	        }
   317	
   318	        let sub_binary = Self { ptr };
   319	        let parent_bytes = parent_bytes(sub_binary.parent())?;
   320	        let end = sub_binary.offset().checked_add(sub_binary.len())?;
   321	        if end > parent_bytes.len() {
   322	            return None;
   323	        }
   324	
   325	        Some(sub_binary)
   326	    }
   327	
   328	    pub fn parent(self) -> Term {
   329	        Term::from_raw(self.word(1))
   330	    }
   331	
   332	    pub fn len(self) -> usize {
   333	        self.word(3) as usize
   334	    }
   335	
   336	    pub fn is_empty(self) -> bool {
   337	        self.len() == 0
   338	    }
   339	
   340	    pub fn as_bytes(self) -> &'static [u8] {
   341	        let bytes = parent_bytes(self.parent()).unwrap_or(&[]);
   342	        let start = self.offset();
   343	        let end = start.checked_add(self.len()).unwrap_or(start);
   344	        bytes.get(start..end).unwrap_or(&[])
   345	    }
   346	
   347	    fn offset(self) -> usize {
   348	        self.word(2) as usize
   349	    }
   350	
   351	    fn word(self, offset: usize) -> u64 {
   352	        // SAFETY: validated SubBinary layout contains fixed payload words.
   353	        unsafe { *self.ptr.add(offset) }
   354	    }
   355	}
   356	
   357	fn parent_bytes(parent: Term) -> Option<&'static [u8]> {
   358	    if let Some(binary) = Binary::new(parent) {
   359	        return Some(binary.as_bytes());
   360	    }
   361	    ProcBin::new(parent).map(ProcBin::as_bytes)
   362	}
   363	
   364	/// Borrowed accessor for a boxed reference.
   365	#[derive(Copy, Clone, Debug)]
   366	pub struct Reference {
   367	    ptr: *const u64,
   368	}
   369	
   370	impl Reference {
   371	    pub fn new(term: Term) -> Option<Self> {
   372	        let ptr = header_ptr(term, BoxedTag::Reference)?;
   373	        if BoxedHeader::size(word_at(ptr, 0)) != 1 {
   374	            return None;
   375	        }
   376	
   377	        Some(Self { ptr })
   378	    }
   379	
   380	    pub fn id(self) -> u64 {
   381	        // SAFETY: reference payload is one u64 id immediately after the header.
   382	        unsafe { *self.ptr.add(1) }
   383	    }
   384	}
   385	
   386	/// Borrowed accessor for a boxed remote PID.
   387	#[derive(Copy, Clone, Debug)]
   388	pub struct ExternalPid {
   389	    ptr: *const u64,
   390	}
   391	
   392	impl ExternalPid {
   393	    pub fn new(term: Term) -> Option<Self> {
   394	        let ptr = header_ptr(term, BoxedTag::ExternalPid)?;
   395	        if BoxedHeader::size(word_at(ptr, 0)) != 3
   396	            || Term::from_raw(word_at(ptr, 1)).as_atom().is_none()
   397	        {
   398	            return None;
   399	        }
   400	
   401	        Some(Self { ptr })
   402	    }
   403	
   404	    pub fn node(self) -> Option<Atom> {
   405	        Term::from_raw(self.word(1)).as_atom()
   406	    }
   407	
   408	    pub fn pid_number(self) -> u64 {
   409	        self.word(2)
   410	    }
   411	
   412	    pub fn serial(self) -> u64 {
   413	        self.word(3)
   414	    }
   415	
   416	    fn word(self, offset: usize) -> u64 {
   417	        // SAFETY: external PID payload contains fixed words after the header.
   418	        unsafe { *self.ptr.add(offset) }
   419	    }
   420	}
   421	
   422	/// Borrowed accessor for a boxed remote reference.
   423	#[derive(Copy, Clone, Debug)]
   424	pub struct ExternalReference {
   425	    ptr: *const u64,
   426	}
   427	
   428	impl ExternalReference {
   429	    pub fn new(term: Term) -> Option<Self> {
   430	        let ptr = header_ptr(term, BoxedTag::ExternalReference)?;
   431	        if BoxedHeader::size(word_at(ptr, 0)) != 2
   432	            || Term::from_raw(word_at(ptr, 1)).as_atom().is_none()
   433	        {
   434	            return None;
   435	        }
   436	
   437	        Some(Self { ptr })
   438	    }
   439	
   440	    pub fn node(self) -> Option<Atom> {
   441	        Term::from_raw(self.word(1)).as_atom()
   442	    }
   443	
   444	    pub fn id(self) -> u64 {
   445	        self.word(2)
   446	    }
   447	
   448	    fn word(self, offset: usize) -> u64 {
   449	        // SAFETY: external reference payload contains fixed words after the header.
   450	        unsafe { *self.ptr.add(offset) }
   451	    }
   452	}
   453	
   454	fn word_at(ptr: *const u64, offset: usize) -> u64 {
   455	    // SAFETY: caller has verified that `ptr` is a boxed object header pointer.
   456	    unsafe { *ptr.add(offset) }
   457	}
   458	
   459	fn header_ptr(term: Term, expected_tag: BoxedTag) -> Option<*const u64> {
   460	    if !term.is_boxed() {
   461	        return None;
   462	    }
   463	
   464	    let ptr = term.heap_ptr()?;
   465	    // SAFETY: boxed terms point to a header word in caller-owned heap storage.
   466	    let header = unsafe { *ptr };
   467	    if BoxedHeader::tag(header) == Some(expected_tag) {
   468	        Some(ptr)
   469	    } else {
   470	        None
   471	    }
   472	}

