     1	//! Binary and bitstring representation.
     2	//!
     3	//! This brief implements inline heap binaries: a boxed binary header, followed
     4	//! by the byte length and byte data packed directly into heap words.
     5	
     6	use crate::term::{
     7	    Term,
     8	    boxed::{BoxedHeader, BoxedTag},
     9	};
    10	
    11	const WORD_BYTES: usize = std::mem::size_of::<u64>();
    12	
    13	/// Number of heap words required to store `byte_len` bytes.
    14	pub const fn packed_word_count(byte_len: usize) -> usize {
    15	    byte_len.div_ceil(WORD_BYTES)
    16	}
    17	
    18	/// Writes an inline binary layout (`header, byte_len, packed bytes...`) into `heap`.
    19	pub fn write_binary(heap: &mut [u64], bytes: &[u8]) -> Option<Term> {
    20	    let data_words = packed_word_count(bytes.len());
    21	    let required_words = 2 + data_words;
    22	    if heap.len() < required_words {
    23	        return None;
    24	    }
    25	
    26	    heap[0] = BoxedHeader::new(BoxedTag::Binary, 1 + data_words);
    27	    heap[1] = bytes.len() as u64;
    28	    heap[2..required_words].fill(0);
    29	
    30	    for (index, byte) in bytes.iter().copied().enumerate() {
    31	        let word_index = 2 + index / WORD_BYTES;
    32	        let shift = (index % WORD_BYTES) * u8::BITS as usize;
    33	        heap[word_index] |= u64::from(byte) << shift;
    34	    }
    35	
    36	    Some(Term::boxed_ptr(heap.as_ptr()))
    37	}
    38	
    39	/// Borrowed accessor for an inline heap binary.
    40	#[derive(Copy, Clone, Debug)]
    41	pub struct Binary {
    42	    ptr: *const u64,
    43	}
    44	
    45	impl Binary {
    46	    pub fn new(term: Term) -> Option<Self> {
    47	        if !term.is_boxed() {
    48	            return None;
    49	        }
    50	
    51	        let ptr = term.heap_ptr()?;
    52	        // SAFETY: boxed binary terms point at a header word in live heap storage.
    53	        let header = unsafe { *ptr };
    54	        if BoxedHeader::tag(header) == Some(BoxedTag::Binary) {
    55	            Some(Self { ptr })
    56	        } else {
    57	            None
    58	        }
    59	    }
    60	
    61	    pub fn len(self) -> usize {
    62	        // SAFETY: binary length is the first payload word after the header.
    63	        unsafe { *self.ptr.add(1) as usize }
    64	    }
    65	
    66	    pub fn is_empty(self) -> bool {
    67	        self.len() == 0
    68	    }
    69	
    70	    pub fn as_bytes(self) -> &'static [u8] {
    71	        let len = self.len();
    72	        // SAFETY: inline binary data starts after header and length. Bytes are
    73	        // packed in native little-endian word order by write_binary; tests and
    74	        // consumers read the same in-process representation.
    75	        unsafe { std::slice::from_raw_parts(self.ptr.add(2).cast::<u8>(), len) }
    76	    }
    77	}
    78	
    79	#[cfg(test)]
    80	mod tests {
    81	    use super::*;
    82	
    83	    #[test]
    84	    fn five_byte_binary_occupies_three_words_and_round_trips_bytes() {
    85	        let bytes = b"hello";
    86	        let mut heap = [0_u64; 3];
    87	        let term = write_binary(&mut heap, bytes).expect("binary should fit");
    88	        let binary = Binary::new(term).expect("binary accessor");
    89	
    90	        assert!(term.is_boxed());
    91	        assert_eq!(BoxedHeader::tag(heap[0]), Some(BoxedTag::Binary));
    92	        assert_eq!(BoxedHeader::size(heap[0]), 2);
    93	        assert_eq!(packed_word_count(bytes.len()), 1);
    94	        assert_eq!(heap.len(), 3);
    95	        assert_eq!(binary.len(), 5);
    96	        assert_eq!(binary.as_bytes(), bytes);
    97	    }
    98	
    99	    #[test]
   100	    fn empty_binary_is_valid_with_zero_length() {
   101	        let mut heap = [0_u64; 2];
   102	        let term = write_binary(&mut heap, &[]).expect("empty binary should fit");
   103	        let binary = Binary::new(term).expect("binary accessor");
   104	
   105	        assert_eq!(BoxedHeader::tag(heap[0]), Some(BoxedTag::Binary));
   106	        assert_eq!(BoxedHeader::size(heap[0]), 1);
   107	        assert_eq!(binary.len(), 0);
   108	        assert!(binary.is_empty());
   109	        assert_eq!(binary.as_bytes(), b"");
   110	    }
   111	
   112	    #[test]
   113	    fn binary_writer_rejects_too_small_heap_slice() {
   114	        let mut heap = [0_u64; 2];
   115	        assert_eq!(write_binary(&mut heap, b"hello"), None);
   116	    }
   117	}

