     1	//! Unified accessor for inline and off-heap binaries.
     2	
     3	use crate::term::{
     4	    Term,
     5	    binary::Binary,
     6	    boxed::{ProcBin, SubBinary},
     7	};
     8	
     9	/// Borrowed binary accessor that hides whether bytes are inline or off-heap.
    10	#[derive(Copy, Clone, Debug)]
    11	pub enum BinaryRef {
    12	    Inline(Binary),
    13	    Refc(ProcBin),
    14	    Sub(SubBinary),
    15	}
    16	
    17	impl BinaryRef {
    18	    /// Creates a binary accessor for inline binaries, ProcBins, or SubBinaries.
    19	    pub fn new(term: Term) -> Option<Self> {
    20	        if let Some(binary) = Binary::new(term) {
    21	            return Some(Self::Inline(binary));
    22	        }
    23	        if let Some(proc_bin) = ProcBin::new(term) {
    24	            return Some(Self::Refc(proc_bin));
    25	        }
    26	        SubBinary::new(term).map(Self::Sub)
    27	    }
    28	
    29	    /// Returns binary bytes without copying the backing storage.
    30	    pub fn as_bytes(&self) -> &'static [u8] {
    31	        match self {
    32	            Self::Inline(binary) => binary.as_bytes(),
    33	            Self::Refc(proc_bin) => proc_bin.as_bytes(),
    34	            Self::Sub(sub_binary) => sub_binary.as_bytes(),
    35	        }
    36	    }
    37	
    38	    /// Returns the number of bytes in this binary.
    39	    pub fn len(&self) -> usize {
    40	        match self {
    41	            Self::Inline(binary) => binary.len(),
    42	            Self::Refc(proc_bin) => proc_bin.len(),
    43	            Self::Sub(sub_binary) => sub_binary.len(),
    44	        }
    45	    }
    46	
    47	    /// Returns true when this binary contains no bytes.
    48	    pub fn is_empty(&self) -> bool {
    49	        self.len() == 0
    50	    }
    51	}
    52	
    53	#[cfg(test)]
    54	mod tests {
    55	    use super::*;
    56	    use crate::term::{
    57	        binary::write_binary,
    58	        shared_binary::{SharedBinary, write_proc_bin},
    59	        sub_binary::write_sub_binary,
    60	    };
    61	
    62	    #[test]
    63	    fn binary_ref_wraps_inline_binary() {
    64	        let mut heap = [0_u64; 3];
    65	        let term = write_binary(&mut heap, b"hello").expect("inline binary fits");
    66	        let binary = BinaryRef::new(term).expect("binary ref");
    67	
    68	        assert!(matches!(binary, BinaryRef::Inline(_)));
    69	        assert_eq!(binary.len(), 5);
    70	        assert_eq!(binary.as_bytes(), b"hello");
    71	    }
    72	
    73	    #[test]
    74	    fn binary_ref_wraps_proc_bin() {
    75	        let shared = SharedBinary::new(b"off-heap".to_vec());
    76	        let mut heap = [0_u64; 3];
    77	        let term = write_proc_bin(&mut heap, &shared).expect("proc bin fits");
    78	        let binary = BinaryRef::new(term).expect("binary ref");
    79	
    80	        assert!(matches!(binary, BinaryRef::Refc(_)));
    81	        assert_eq!(binary.len(), 8);
    82	        assert_eq!(binary.as_bytes(), b"off-heap");
    83	    }
    84	
    85	    #[test]
    86	    fn binary_ref_wraps_sub_binary() {
    87	        let shared = SharedBinary::new(b"0123456789abcdef".to_vec());
    88	        let mut proc_heap = [0_u64; 3];
    89	        let parent = write_proc_bin(&mut proc_heap, &shared).expect("proc bin fits");
    90	        let mut sub_heap = [0_u64; 5];
    91	        let term = write_sub_binary(&mut sub_heap, parent, 4, 6).expect("sub binary fits");
    92	        let binary = BinaryRef::new(term).expect("binary ref");
    93	
    94	        assert!(matches!(binary, BinaryRef::Sub(_)));
    95	        assert_eq!(binary.len(), 6);
    96	        assert_eq!(binary.as_bytes(), b"456789");
    97	    }
