//! GREEN: the same four programs, with the witness supplied. Each still holds
//! the slice across a GC-triggering call, and each is now a BORROW ERROR.
use beamr::gc;
use beamr::process::Process;
use beamr::term::binary::{Binary, write_binary};
use beamr::term::binary_ref::BinaryRef;
use beamr::term::boxed::{BigInt, ProcBin, SubBinary, write_bigint};
use beamr::term::shared_binary::{SharedBinary, write_proc_bin};
use beamr::term::sub_binary::write_sub_binary;

#[test]
fn procbin_as_bytes_cannot_outlive_the_arc_it_points_at() {
    let mut process = Process::new(1, 233);
    let shared = SharedBinary::new(b"off-heap".to_vec());
    let words = process.heap_mut().alloc_slice_maybe_refcounted(3).expect("words");
    let term = write_proc_bin(words, &shared).expect("proc bin");
    let bytes = ProcBin::new(term).expect("accessor").as_bytes(process.borrow_terms());
    let _ = gc::collect_minor(&mut process);
    assert_eq!(bytes, b"off-heap");
}

#[test]
fn inline_binary_as_bytes_cannot_outlive_the_heap_words() {
    let mut process = Process::new(2, 233);
    let words = process.heap_mut().alloc_slice(3).expect("words");
    let term = write_binary(words, b"hello").expect("binary");
    let bytes = Binary::new(term).expect("accessor").as_bytes(process.borrow_terms());
    let _ = gc::collect_minor(&mut process);
    assert_eq!(bytes, b"hello");
}

#[test]
fn bigint_limbs_cannot_outlive_the_heap_words() {
    let mut process = Process::new(3, 233);
    let words = process.heap_mut().alloc_slice(5).expect("words");
    let term = write_bigint(words, false, &[7, 9]).expect("bigint");
    let limbs = BigInt::new(term).expect("accessor").limbs(process.borrow_terms());
    let _ = gc::collect_minor(&mut process);
    assert_eq!(limbs, &[7, 9]);
}

#[test]
fn sub_binary_as_bytes_cannot_outlive_the_parent() {
    let mut process = Process::new(4, 233);
    let parent_words = process.heap_mut().alloc_slice(4).expect("parent");
    let parent = write_binary(parent_words, b"0123456789abcdef").expect("binary");
    let sub_words = process.heap_mut().alloc_slice(5).expect("sub");
    let term = write_sub_binary(sub_words, parent, 4, 6).expect("sub binary");
    let bytes = SubBinary::new(term).expect("accessor").as_bytes(process.borrow_terms());
    let _ = gc::collect_minor(&mut process);
    assert_eq!(bytes, b"456789");
}

#[test]
fn binary_ref_as_bytes_cannot_outlive_the_heap_words() {
    let mut process = Process::new(5, 233);
    let words = process.heap_mut().alloc_slice(3).expect("words");
    let term = write_binary(words, b"hello").expect("binary");
    let bytes = BinaryRef::new(term).expect("accessor").as_bytes(process.borrow_terms());
    let _ = gc::collect_minor(&mut process);
    assert_eq!(bytes, b"hello");
}
